'use strict';
const $ = (s, parent=document) => parent.querySelector(s);
const $$ = (s, parent=document) => [...parent.querySelectorAll(s)];
const esc = (x='') => String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = x => Number.isFinite(+x) ? +x : 0;
const money = (v, currency='USD') => `${v<0?'−':'+'}${currency==='BRL'?'R$':'$'} ${Math.abs(num(v)).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const amount = (v, currency='USD') => `${currency==='BRL'?'R$':'$'} ${num(v).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const fnum=(v,d=2)=>num(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const localDate = (d=new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const datePt = (s) => {if(!s)return '—'; const [y,m,d]=s.split('-');return `${d}/${m}/${y}`};
const pct = x => `${fnum(x,1)}%`;
const col = x => num(x)>0?'positive':num(x)<0?'negative':'';
const imgSrc = s => typeof s==='string' && s.startsWith('/uploads/')?s:'';
const timefmt = s => {s=Math.max(0,Math.floor(s||0));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')};
const formatWeek = (s) => ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][new Date(s+'T12:00:00').getDay()];
const fields = {'date':'date','start':'start','end':'end','asset':'asset','market':'market','direction':'direction','strategy':'strategy','accountId':'accountId','accountType':'accountType','entry':'entry','exit':'exit','stop':'stop','target1':'target1','target2':'target2','target3':'target3','pnl':'pnl','fees':'fees','risk':'risk','rr':'rr','timeframe':'timeframe','trend':'trend','notes':'notes','analysis':'analysis','planning':'planning','psychology':'psychology','review':'review','good':'good','improve':'improve','mistakes':'mistakes','lessons':'lessons','followed':'followed','impulsive':'impulsive','revenge':'revenge','confidence':'confidence','discipline':'discipline','tag':'tag','currency':'currency'};
const basePrefs={theme:'light',primary:'#635cf6',columns:5,preset:'Padrão',compact:false,blocks:['equity','distribution','assets','strategies','weekdays','hours','metrics','performance']};
let S={trades:[],accounts:[],strategies:[],books:[],sessions:[],timer:{running:0,elapsed:0},settings:{}};
let P={...basePrefs};
let page='dashboard', formTab='Análise', draft={}, editingId=null, calendarAt=new Date(), selectedDay='', activeBook=null;
let study={tradeId:null,index:0,tool:'pen',color:'#fe4d4d',width:4,undo:[]};
let lastReportDates={start:'',end:''};
const tabs=['Análise','Básico','Resultado','Psicologia','Planejamento','Contexto','Revisão'];

async function api(path,data){let r=await fetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let j;try{j=await r.json()}catch(e){throw new Error('Resposta inválida do servidor')};if(!r.ok)throw new Error(j.error||'Falha na operação');return j}
async function reload(){S=await api('/api/state');P={...basePrefs,...(S.settings.preferences||{})};applyPrefs();updateTimer();return S}
function toast(message){$('#toastRoot').innerHTML=`<div class="toast">${esc(message)}</div>`;setTimeout(()=>{$('#toastRoot').innerHTML=''},4300)}
async function run(fn){try{await fn()}catch(e){console.error(e);toast(e.message||'Erro inesperado')}}
function applyPrefs(){document.documentElement.setAttribute('data-theme',P.theme);document.documentElement.style.setProperty('--primary',P.primary);document.documentElement.style.setProperty('--columns',P.columns);$('#shell').className='shell '+(P.compact?'compact ':'')+'view-'+({'Padrão':'standard','Compacto':'compact','Analítico':'analytic','Minimalista':'minimal'}[P.preset]||'standard');const pro=S.settings.profile||{};const av=$('#avatarMini');if(pro.avatar){av.style.backgroundImage=`url('${imgSrc(pro.avatar)}')`;av.textContent=''}else{av.style.backgroundImage='';av.textContent=(pro.name||'DT').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}}
async function saveSettings(key,value){await api('/api/settings',{key,value});S.settings[key]=value;if(key==='preferences'){P={...basePrefs,...value};applyPrefs()}}
function nav(p){page=p;$('#sidebar').classList.remove('open');$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render()}
function header(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="muted">${subtitle}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`}
function btn(label,action,variant='',attrs=''){return `<button class="btn ${variant}" data-action="${action}" ${attrs}>${label}</button>`}
function cardTitle(t){return `<h3 class="section-title">${esc(t)}</h3>`}
function blank(title,message,action='',label=''){return `<div class="empty"><span class="emoji">▧</span><strong>${esc(title)}</strong><p>${esc(message)}</p>${action?btn(label,action,'primary'):''}</div>`}
function activeTrades(){return S.trades.filter(t=>!t.noTrade).sort((a,b)=>(a.date+' '+(a.start||'')+' '+String(a.id).padStart(10,'0')).localeCompare(b.date+' '+(b.start||'')+' '+String(b.id).padStart(10,'0')))}
function tnet(t){return num(t.pnl)-num(t.fees)}
function grouped(trades,fn){const r=new Map;for(const t of trades){const k=fn(t);r.set(k,(r.get(k)||0)+tnet(t))}return [...r.entries()].map(([key,value])=>({key,value})).sort((a,b)=>b.value-a.value)}
function metrics(trades=activeTrades()){
 const cash=trades.map(tnet),wins=cash.filter(v=>v>.005),losses=cash.filter(v=>v<-.005),grossPos=wins.reduce((a,b)=>a+b,0),grossNeg=-losses.reduce((a,b)=>a+b,0),sum=cash.reduce((a,b)=>a+b,0);
 let balance=0,high=0,dd=0,winStreak=0,lossStreak=0,maxWins=0,maxLoss=0;const points=[0];
 for(const v of cash){balance+=v;high=Math.max(high,balance);dd=Math.max(dd,high-balance);points.push(balance);winStreak=v>0?winStreak+1:0;lossStreak=v<0?lossStreak+1:0;maxWins=Math.max(maxWins,winStreak);maxLoss=Math.max(maxLoss,lossStreak)}
 const days=new Map;for(const t of trades){days.set(t.date,(days.get(t.date)||0)+tnet(t))}
 const daysWin=[...days.values()].filter(x=>x>0).length;
 const ret={count:cash.length,net:sum,gross:grossPos,winrate:cash.length?(wins.length/cash.length)*100:0,pf:grossNeg?grossPos/grossNeg:(grossPos?Infinity:0),avgGain:wins.length?grossPos/wins.length:0,avgLoss:losses.length?(-grossNeg/losses.length):0,best:cash.length?Math.max(...cash):0,worst:cash.length?Math.min(...cash):0,expectancy:cash.length?sum/cash.length:0,drawdown:dd,avgRR:0,consistency:days.size?daysWin/days.size*100:0,winStreak:maxWins,lossStreak:maxLoss,equity:points,days,wins:wins.length,losses:losses.length,balance};
 const rrs=trades.filter(t=>isFinite(+t.rr) && String(t.rr??'').trim()!=='' && +t.rr!==0).map(t=>+t.rr);
 ret.avgRR=rrs.length?rrs.reduce((a,b)=>a+b,0)/rrs.length:0;return ret;
}
function stat(name,value,icon,cls=''){return `<div class="card stat"><div class="eyebrow">${esc(name)}<i>${icon}</i></div><div class="value ${cls}">${value}</div></div>`}
function chartLine(values,height=245){
 if(!values.length||values.length<2)return blank('Sem dados','Registre operações para visualizar a curva de capital.');
 let w=1100,h=height,pad=32,min=Math.min(0,...values),max=Math.max(...values,0),r=Math.max(1,max-min),x=i=>pad+(i/(values.length-1))*(w-pad*2),y=v=>h-pad-((v-min)/r)*(h-pad*2);
 let path=values.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+','+y(v).toFixed(2)).join(' '),area=path+` L${x(values.length-1)},${h-pad} L${x(0)},${h-pad} Z`;
 const grid=Array.from({length:5},(_,i)=>{const yy=pad+i*(h-2*pad)/4,v=max-i*(max-min)/4;return `<line x1="${pad}" y1="${yy}" x2="${w-pad}" y2="${yy}" stroke="var(--line)" stroke-dasharray="4 4"/><text x="${pad-9}" y="${yy+3}" text-anchor="end" fill="var(--sub)" font-size="11">${fnum(v,0)}</text>`}).join('');
 return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Curva de capital"><defs><linearGradient id="equitygrad" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="${P.primary}" stop-opacity=".20"/><stop offset="100%" stop-color="${P.primary}" stop-opacity=".01"/></linearGradient></defs>${grid}<path d="${area}" fill="url(#equitygrad)"/><path d="${path}" fill="none" stroke="${P.primary}" stroke-width="2.8" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/></svg></div>`;
}
function chartBars(items,limit=8){if(!items.length)return blank('Sem dados','As estatísticas serão exibidas quando houver operações.');const set=items.slice(0,limit),m=Math.max(1,...set.map(x=>Math.abs(x.value)));return set.map(({key,value})=>`<div class="bar-row"><span title="${esc(key)}">${esc(String(key).slice(0,19))}</span><div class="bar-track"><div class="bar-fill ${value<0?'loss':''}" style="width:${Math.max(1,Math.abs(value)/m*100)}%"></div></div><b class="${col(value)}">${money(value)}</b></div>`).join('')}
function donut(m){if(!m.count)return blank('Sem dados','Adicione trades para ver ganhos e perdas.');let n=m.wins+m.losses;let win=n?m.wins/n*100:0;return `<div style="display:flex;align-items:center;justify-content:center;gap:28px;min-height:195px;flex-wrap:wrap"><div style="width:155px;height:155px;border-radius:50%;background:conic-gradient(var(--mint) 0 ${win}%,var(--red) ${win}% 100%);display:grid;place-items:center"><div style="width:103px;height:103px;border-radius:50%;background:var(--surface);display:grid;place-items:center;font-size:21px;font-weight:750">${pct(m.winrate)}</div></div><div><p class="positive">● ${m.wins} Win</p><p class="negative">● ${m.losses} Loss</p><p class="muted">${m.count-m.wins-m.losses} Break Even</p></div></div>`}
function accountOf(t){return S.accounts.find(a=>String(a.id)===String(t.accountId))}
function accountName(t){return accountOf(t)?.name||'Conta removida'}
function recentList(trades,limit=6){if(!trades.length)return blank('Nenhuma operação','Registre sua primeira operação.','newTrade','Nova operação');return [...trades].reverse().slice(0,limit).map(t=>`<div class="data-row" style="padding:9px 0;cursor:pointer" data-action="details" data-id="${t.id}"><span>${datePt(t.date)} · <strong>${esc(t.asset)}</strong> · ${esc(t.direction)}</span><b class="${col(tnet(t))}">${money(tnet(t))}</b></div>`).join('')}
function dashboard(){const t=activeTrades(),m=metrics(t),hours=grouped(t,x=>(x.start||'—').slice(0,2)+'h'),accountSet=S.accounts.map(a=>({name:a.name,capital:a.initial_capital,balance:num(a.initial_capital)+t.filter(x=>String(x.accountId)===String(a.id)).reduce((s,x)=>s+tnet(x),0)}));
 const stats=[['LUCRO LÍQUIDO',amount(m.net),'$','positive'],['WIN RATE',pct(m.winrate),'◎','primary-text'],['PROFIT FACTOR',m.pf===Infinity?'∞':fnum(m.pf),'↗','positive'],['TOTAL TRADES',m.count,'▥','primary-text'],['MÉDIA GAIN',amount(m.avgGain),'↗','positive'],['MÉDIA LOSS',amount(m.avgLoss),'↘','negative'],['MELHOR TRADE',amount(m.best),'♙','positive'],['PIOR TRADE',amount(m.worst),'ϟ','negative'],['EXPECTATIVA',amount(m.expectancy),'∿','primary-text'],['DRAWDOWN MÁX',amount(m.drawdown),'↘','warn'],['MÉDIA R:R',fnum(m.avgRR),'%','primary-text'],['CONSISTÊNCIA',pct(m.consistency),'♨','warn'],['SEQ. VITÓRIAS',m.winStreak,'♙','positive'],['SEQ. DERROTAS',m.lossStreak,'ϟ','negative'],['LUCRO BRUTO',amount(m.gross),'$','positive']];
 const blocks={equity:`<div class="card chart-card">${cardTitle('Curva de Equity')}${chartLine(m.equity)}</div>`,distribution:`<div class="card subcard"><h3>Distribuição Win / Loss</h3>${donut(m)}</div>`,assets:`<div class="card subcard"><h3>Profit por Ativo</h3>${chartBars(grouped(t,x=>x.asset))}</div>`,strategies:`<div class="card subcard"><h3>Profit por Estratégia</h3>${chartBars(grouped(t,x=>x.strategy||'Sem estratégia'))}</div>`,weekdays:`<div class="card subcard"><h3>Profit por Dia da Semana</h3>${chartBars(grouped(t,x=>formatWeek(x.date)))}</div>`,hours:`<div class="card subcard"><h3>Resultado por Horário</h3>${chartBars(hours)}</div>`,metrics:`<div class="card subcard"><h3>Métricas Profissionais</h3>${[['Drawdown máximo',amount(m.drawdown)],['Seq. vitórias',m.winStreak],['Seq. derrotas',m.lossStreak],['Expectativa por trade',amount(m.expectancy)],['Consistência',pct(m.consistency)],['Média R:R',fnum(m.avgRR)],['Profit factor',m.pf===Infinity?'∞':fnum(m.pf)],['Tempo total de estudo',timefmt(S.sessions.reduce((s,r)=>s+num(r.seconds),0))]].map(([k,v])=>`<div class="data-row"><span>${k}</span><b>${v}</b></div>`).join('')}</div>`,performance:`<div class="card subcard"><h3>Análise de Performance</h3>${(()=>{const ba=grouped(t,x=>x.asset),st=grouped(t,x=>x.strategy||'Sem estratégia'),hr=hours;return [['Melhor ativo',ba[0]?.key||'—'],['Pior ativo',ba.at(-1)?.key||'—'],['Melhor estratégia',st[0]?.key||'—'],['Pior estratégia',st.at(-1)?.key||'—'],['Melhor horário',hr[0]?.key||'—'],['Pior horário',hr.at(-1)?.key||'—']].map(([k,v])=>`<div class="data-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('')})()}</div>`};
 const b=(P.blocks||basePrefs.blocks).filter(x=>blocks[x]);const outer=b.filter(x=>x!=='equity');
 return header('Dashboard','Visão geral da sua performance',btn('▧ Relatório','report')+btn('⊕ Nova Operação','newTrade','primary'))+
 `<div class="stats">${stats.map(x=>stat(...x)).join('')}</div>`+
 (b.includes('equity')?blocks.equity:'')+`<div class="grid2">${outer.map(x=>blocks[x]).join('')}</div>`+
 `<div class="grid2"><div class="card subcard"><h3>Operações recentes</h3>${recentList(t)}</div><div class="card subcard"><h3>Capital por conta</h3>${accountSet.length?accountSet.map(a=>`<div class="data-row"><span>${esc(a.name)} <small>(Inicial: ${amount(a.capital)})</small></span><b>${amount(a.balance)}</b></div>`).join(''):blank('Nenhuma conta cadastrada','Na primeira operação você informa o capital inicial da conta.')}</div></div>`;
}
function field(label,name,type='text',extra=''){const v=draft[name]??'';return `<div class="field"><label for="f_${name}">${esc(label)}</label><input id="f_${name}" type="${type}" data-field="${name}" value="${esc(v)}" ${extra}></div>`}
function area(label,name,placeholder='',rows=4){return `<div class="field field-full"><label>${esc(label)}</label><textarea data-field="${name}" rows="${rows}" placeholder="${esc(placeholder)}">${esc(draft[name]||'')}</textarea></div>`}
function selectField(label,name,values,placeholder='Selecione'){const val=draft[name]||'';return `<div class="field"><label>${esc(label)}</label><select data-field="${name}"><option value="">${esc(placeholder)}</option>${values.map(x=>{let value=Array.isArray(x)?x[0]:x,display=Array.isArray(x)?x[1]:x;return `<option value="${esc(value)}" ${String(val)===String(value)?'selected':''}>${esc(display)}</option>`}).join('')}</select></div>`}
function imgsHtml(){return `<div class="field field-full"><label>Prints do gráfico</label><div class="upload" data-action="uploadImage">↥ &nbsp; Clique para anexar prints (PNG, JPG, WEBP) ou cole com <b>Ctrl + V</b></div><div class="helper">As imagens ficam salvas somente neste computador. Limite: 14 MB por imagem.</div><div class="thumbs">${(draft.images||[]).map((src,i)=>`<div class="thumb"><img src="${esc(src)}" data-action="previewDraft" data-index="${i}" alt="Print ${i+1}"><button class="remove" data-action="removeDraftImage" data-index="${i}" title="Excluir print">✕</button></div>`).join('')}</div></div>`}
function tabContent(){switch(formTab){
case 'Análise':return `<div class="form-grid">${imgsHtml()}${area('Texto da Análise','analysis','Explique sua leitura de mercado, contexto, motivos da entrada, regiões importantes, gerenciamento planejado e observações relevantes...',7)}</div>`;
case 'Básico':return `<div class="form-grid">${field('Data','date','date')}${field('Horário de entrada','start','time')}${field('Horário de saída','end','time')}<div class="field"><label>Duração</label><input type="text" value="${duration(draft.start,draft.end)}" disabled></div>${field('Ativo','asset','text','list="assetSuggest" placeholder="Ex.: NASDAQ, XAUUSD, USTEC"')}${selectField('Mercado','market',['Futuros','Forex','CFD','Ações','Opções','Criptomoedas','Outros'])}${selectField('Tipo de Operação','direction',['Compra','Venda'])}<div class="field"><label>Estratégia</label><div class="chiprow"><select data-field="strategy" style="flex:1;min-width:130px"><option value="">Selecione</option>${S.strategies.map(x=>`<option ${draft.strategy===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn small" data-action="addStrategy" title="Cadastrar e salvar estratégia">+ Nova</button></div></div><div class="field"><label>Tipo de Conta</label><input value="${esc(S.accounts.find(a=>String(a.id)===String(draft.accountId))?.kind||'Definido pela conta')}" disabled></div><div class="field"><label>Nome da Conta</label><div class="chiprow"><select data-field="accountId" style="flex:1;min-width:130px"><option value="">Selecione</option>${S.accounts.map(a=>`<option value="${a.id}" ${String(draft.accountId)===String(a.id)?'selected':''}>${esc(a.name)} · ${esc(a.kind)} · ${amount(a.initial_capital,a.currency)}</option>`).join('')}</select><button class="btn small" data-action="addAccount">+ Nova</button></div></div><datalist id="assetSuggest"><option value="NASDAQ"><option value="USTEC"><option value="XAUUSD"><option value="US30"><option value="ES"><option value="NQ"><option value="SPX"><option value="DXY"></datalist></div><p class="info-note" style="margin-top:18px">Uma conta nova exige informar o capital inicial. Você pode cadastrar quantas contas e estratégias quiser, e elas ficarão disponíveis nos próximos trades.</p>`;
case 'Resultado':return `<div class="form-grid">${field('Preço de Entrada','entry','number','step="any"')}${field('Preço de Saída','exit','number','step="any"')}${field('Preço do Stop','stop','number','step="any"')}${field('Risco Financeiro ($)','risk','number','step="any" placeholder="Ex.: 30"')}${field('Resultado Financeiro Bruto ($)','pnl','number','step="any" placeholder="Ex.: 50 ou -20"')}${field('Custos / Taxas ($)','fees','number','step="any" placeholder="Ex.: 1.20"')}<div class="field"><label>Resultado em Pontos</label><input id="computedPoints" disabled></div><div class="field"><label>Resultado Líquido</label><input id="computedNet" disabled></div><div class="field"><label>Resultado % sobre capital inicial</label><input id="computedPct" disabled></div><div class="field"><label>Resultado R:R (calculado pelo risco)</label><input id="computedRR" disabled></div><p class="info-note field-full">O P&L informado é o resultado bruto da posição. O líquido desconta as taxas. O resultado em pontos respeita Compra/Venda. Para calcular o R:R realizado, informe o risco financeiro da operação.</p></div>`;
case 'Psicologia':return `<div class="form-grid">${selectField('Seguiu seu plano?','followed',['Sim','Não','Parcialmente'])}${selectField('Operou por impulso?','impulsive',['Não','Sim'])}${selectField('Fez revenge trade?','revenge',['Não','Sim'])}${field('Confiança (0 a 10)','confidence','number','min="0" max="10"')}${field('Disciplina (0 a 10)','discipline','number','min="0" max="10"')}${area('Emoções e comportamento','psychology','Como você se sentiu durante a operação?')}</div>`;
case 'Planejamento':return `<div class="form-grid">${field('Alvo 1','target1','number','step="any"')}${field('Alvo 2','target2','number','step="any"')}${field('Alvo 3','target3','number','step="any"')}${area('Gerenciamento e plano de execução','planning','Sua hipótese, invalidadores, parciais, gerenciamento e limites...',5)}</div>`;
case 'Contexto':return `<div class="form-grid">${selectField('Timeframe','timeframe',['15 Segundos','30 Segundos','1 Minuto','2 Minutos','3 Minutos','5 Minutos','15 Minutos','30 Minutos','1 Hora','4 Horas','Diário','Semanal'])}${selectField('Tendência do Mercado','trend',['Alta','Baixa','Lateral'])}${area('Contexto de mercado','notes','Ex.: tendência, notícias, suporte, resistência, VWAP, GEX...',5)}</div>`;
case 'Revisão':return `<div class="form-grid">${area('Análise pós-operação','review','O trade se desenvolveu como você esperava?')}${area('O que fez bem','good')}${area('O que precisa melhorar','improve')}${area('Erros cometidos','mistakes')}${area('Aprendizados','lessons')}<div class="field field-full"><label>Nota geral</label><div class="star-rating">${[1,2,3,4,5].map(n=>`<button type="button" data-action="rate" data-val="${n}" class="${num(draft.rating)>=n?'on':''}">★</button>`).join('')}</div></div>${field('Tags (separadas por vírgula)','tag','text','placeholder="Ex.: setup A, manhã, tendência"')}<div class="field"><label>Favoritar este trade</label><div class="switch-row"><input type="checkbox" data-field="favorite" ${draft.favorite?'checked':''}> <span class="muted">Destacar no Feed</span></div></div>${imgsHtml()}</div>`;
}}
function duration(start,end){if(!start||!end)return 'Calculada automaticamente';const [a,b]=[start,end].map(s=>{let x=s.split(':').map(Number);return x[0]*60+x[1]});let v=b-a;if(v<0)v+=1440;return `${Math.floor(v/60)?Math.floor(v/60)+'h ':''}${v%60}min`}
function newTrade(){draft={date:localDate(),start:'',end:'',asset:'',market:'Futuros',direction:'Compra',strategy:'',accountId:S.accounts[0]?.id||'',images:[],pnl:'',fees:'',noTrade:false,rating:3};editingId=null;formTab='Análise';nav('operation')}
function editTrade(id){const t=S.trades.find(x=>x.id===+id);if(!t)return;draft=structuredClone(t);editingId=t.id;formTab='Análise';nav('operation')}
function operation(){return `<div class="form-wrap">${header(editingId?'Editar Operação':'Análise / Operação','Registre todos os detalhes do trade',btn('← Voltar ao Feed','goFeed',''))}<div class="notice"><input type="checkbox" data-field="noTrade" ${draft.noTrade?'checked':''}><div><strong>Hoje não operei</strong><small>Marque se decidiu não operar neste dia. Registra um dia sem operações, sem interferir nos resultados financeiros.</small></div></div>${draft.noTrade?`<div class="card pad"><div class="form-grid">${field('Data','date','date')}${area('Por que não operei?','notes','Sua decisão e aprendizados do dia...',3)}</div></div>`:`<div class="tabbar">${tabs.map(t=>`<button data-action="tab" data-tab="${esc(t)}" class="${formTab===t?'active':''}">${esc(t)}</button>`).join('')}</div><div class="card pad">${tabContent()}</div>`}<div class="form-actions">${btn('Cancelar','goFeed')}${btn(editingId?'Salvar alterações':'Registrar Operação','saveTrade','primary')}</div></div>`}
function computed(){const points=(num(draft.exit)-num(draft.entry))*(draft.direction==='Venda'?-1:1),net=num(draft.pnl)-num(draft.fees),risk=Math.abs(num(draft.risk)),account=S.accounts.find(x=>String(x.id)===String(draft.accountId));const rr=risk?net/risk:0;draft.rr=risk?String(rr):'';if($('#computedPoints'))$('#computedPoints').value=(draft.exit!==''&&draft.entry!==''?fnum(points):'—');if($('#computedNet'))$('#computedNet').value=amount(net);if($('#computedPct'))$('#computedPct').value=account?.initial_capital?`${pct(net/account.initial_capital*100)} (capital inicial)`:'—';if($('#computedRR'))$('#computedRR').value=risk?`${fnum(rr)} R`:'—'}
async function uploadImages(files){for(let f of files){if(!f.type.startsWith('image/')){toast('Use uma imagem PNG, JPG, WEBP ou GIF');continue}let data=await readData(f);let p=await api('/api/upload',{data});draft.images??=[];draft.images.push(p.path)}render()}
function readData(file){return new Promise((ok,fail)=>{let r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>fail(new Error('Erro de leitura do arquivo'));r.readAsDataURL(file)})}
async function saveTrade(){draft.date ||= localDate();draft.images||=[];let p={...draft};delete p.id;p.accountId=p.accountId?Number(p.accountId):null;if(!p.noTrade){p.rr=p.risk?String((num(p.pnl)-num(p.fees))/Math.abs(num(p.risk))):'';if(!p.asset?.trim())throw Error('Informe o ativo na aba Básico');if(!p.accountId)throw Error('Escolha uma conta na aba Básico, ou cadastre uma nova');}const out=await api('/api/trades',{id:editingId,trade:p});await reload();toast(editingId?'Operação atualizada':'Operação registrada com sucesso');nav('feed')}
function feed(){const t=[...S.trades].sort((a,b)=>((b.date||'')+(b.start||'')).localeCompare((a.date||'')+(a.start||'')));
 return header('Feed','Suas operações recentes',btn('⊕ Nova Operação','newTrade','primary'))+(t.length?`<div class="feed-grid">${t.map(x=>`<article class="card feed-card" data-action="details" data-id="${x.id}"><div class="feed-top"><div><strong>${esc(x.noTrade?'Não operei':x.asset)}</strong> <span class="pill">${esc(x.strategy||'Sem estratégia')}</span> ${x.favorite?'⭐':''}</div><strong class="${col(tnet(x))}">${x.noTrade?'—':money(tnet(x))}</strong></div><div class="feed-info"><span>▦ ${datePt(x.date)}</span><span>◷ ${esc(x.start||'—')}</span><span>${esc(x.market||'')}</span><span>${esc(x.direction||'')}</span><span>${esc(accountName(x))}</span></div>${x.images?.length?`<div class="feed-pic" data-action="study" data-id="${x.id}" data-index="0"><img src="${esc(x.images[0])}" alt="Print do trade ${esc(x.asset)}"></div>`:`<div class="feed-pic empty-pic">${x.noTrade?'Dia sem operação':'Sem print anexado'}</div>`}<div class="feed-footer"><span class="muted">${esc((x.analysis||x.review||'').slice(0,100))}</span><a data-action="details" data-id="${x.id}">Ver detalhes →</a></div></article>`).join('')}</div>`:blank('Seu feed está vazio','Adicione sua primeira operação para começar a registrar o histórico.','newTrade','Registrar operação'))}
function details(id){const t=S.trades.find(x=>x.id===+id);if(!t)return;let rating='★'.repeat(num(t.rating))+'☆'.repeat(5-num(t.rating));let durationText=duration(t.start,t.end);return `<div class="form-wrap">${header(esc(t.asset||'Dia sem operações'),`${datePt(t.date)} · ${esc(t.start||'—')}–${esc(t.end||'—')}`,btn('✎ Editar','editTrade','',`data-id="${t.id}"`)+btn('♜ Excluir','deleteTrade','danger',`data-id="${t.id}"`))}<div class="details-top ${tnet(t)<0?'negative':''}"><small style="font-size:11px;display:block;opacity:.7">RESULTADO LÍQUIDO</small>${t.noTrade?'Não operei':money(tnet(t))}</div><div class="details-layout"><div class="card"><h3>Informações</h3>${[['Mercado',t.market],['Direção',t.direction],['Estratégia',t.strategy],['Ativo',t.asset],['Duração',durationText],['Timeframe',t.timeframe],['Conta',accountName(t)]].map(([l,v])=>`<div class="data-row"><span>${l}</span><b>${esc(v||'—')}</b></div>`).join('')}</div><div class="card"><h3>Gerenciamento</h3>${[['Entrada',t.entry],['Saída',t.exit],['Stop',t.stop],['Risco',t.risk?amount(t.risk):'—'],['P&L bruto',amount(t.pnl)],['Taxas',amount(t.fees)],['Alvo 1',t.target1],['Alvo 2',t.target2],['Alvo 3',t.target3],['R:R realizado',t.rr?fnum(t.rr)+' R':'—']].map(([l,v])=>`<div class="data-row"><span>${l}</span><b>${esc(v??'—')}</b></div>`).join('')}</div><div class="card"><h3>Psicologia</h3>${[['Seguiu plano',t.followed],['Impulso',t.impulsive],['Revenge',t.revenge],['Confiança',t.confidence?`${t.confidence}/10`:'—'],['Disciplina',t.discipline?`${t.discipline}/10`:'—']].map(([l,v])=>`<div class="data-row"><span>${l}</span><b>${esc(v||'—')}</b></div>`).join('')}</div><div class="card"><h3>Avaliação</h3><div class="rating" style="font-size:23px;margin:20px 0">${rating}</div><p class="muted">${esc(t.tag||'Sem tags')}</p></div></div><div class="card pad" style="margin-top:15px"><h3 class="section-title">Análises e aprendizados</h3>${[['Análise pré-trade','analysis'],['Planejamento','planning'],['Contexto','notes'],['Psicologia','psychology'],['Revisão','review'],['O que fez bem','good'],['Melhorias','improve'],['Erros','mistakes'],['Aprendizados','lessons']].filter(x=>t[x[1]]).map(([l,k])=>`<h4>${l}</h4><p style="white-space:pre-wrap;line-height:1.65">${esc(t[k])}</p>`).join('')||'<p class="muted">Nenhuma anotação adicionada.</p>'}${t.images?.length?`<h4>Prints</h4><div class="thumbs">${t.images.map((x,i)=>`<div class="thumb"><img src="${esc(x)}" data-action="study" data-id="${t.id}" data-index="${i}"></div>`).join('')}</div>`:''}</div></div>`}
function calendar(){const year=calendarAt.getFullYear(),month=calendarAt.getMonth(),first=new Date(year,month,1).getDay(),last=new Date(year,month+1,0).getDate(),name=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(calendarAt),prefix=`${year}-${String(month+1).padStart(2,'0')}`;
 const dayTrades=activeTrades().filter(t=>t.date.startsWith(prefix)),metric=metrics(dayTrades),today=localDate();const current=selectedDay.startsWith(prefix)?selectedDay:'';
 const cells=Array.from({length:first},()=>`<button class="cal-cell" disabled></button>`).concat(Array.from({length:last},(_,i)=>{const day=i+1,s=`${prefix}-${String(day).padStart(2,'0')}`,list=dayTrades.filter(t=>t.date===s),v=list.reduce((a,x)=>a+tnet(x),0),noOps=S.trades.some(t=>t.date===s && t.noTrade);
 return `<button class="cal-cell ${list.length?(v>0?'gain':v<0?'lose':''):''} ${s===today?'today':''} ${current===s?'chosen':''}" data-action="calendarDay" data-date="${s}"><span class="daynum">${day}</span>${list.length?`<b class="${col(v)}">${money(v)}</b><small>${list.length} op.</small>`:noOps?'<small>Não operei</small>':''}</button>`}));
 const selected=selectedDay ? S.trades.filter(t=>t.date===selectedDay) : [];
 return header('Calendário','Visualize seus resultados diários')+`<div class="calendar-top"><div class="card"><label>Trades do Mês</label><strong>${metric.count}</strong></div><div class="card"><label>P&L do Mês</label><strong class="${col(metric.net)}">${money(metric.net)}</strong></div><div class="card"><label>Win Rate</label><strong class="primary-text">${pct(metric.winrate)}</strong></div></div><div class="card calendar-card"><div class="cal-head">${btn('‹','prevMonth','small')}<strong style="text-transform:capitalize">${esc(name)}</strong>${btn('›','nextMonth','small')}</div><div class="cal-grid">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=>`<div class="cal-week">${x}</div>`).join('')}${cells.join('')}</div></div>${selectedDay?`<div class="card day-detail"><div class="feed-top"><strong>Operações de ${datePt(selectedDay)}</strong><div class="actions"><b class="${col(selected.reduce((s,t)=>s+tnet(t),0))}">${money(selected.reduce((s,t)=>s+tnet(t),0))}</b>${btn('✕','closeDay','small')}</div></div>${selected.length?selected.map(t=>`<div class="day-item" data-action="details" data-id="${t.id}"><span><b>${esc(t.noTrade?'Não operei':t.asset)}</b> · ${esc(t.direction||'')} <small>(${esc(t.start||'—')})</small></span><b class="${col(tnet(t))}">${t.noTrade?'—':money(tnet(t))}</b></div>`).join(''):'<p class="muted">Nenhuma operação registrada nessa data.</p>'}</div>`:''}`
}
const planBase={daily:'',weekly:'',monthly:'',risk:'1',dailyLoss:'',weeklyLoss:'',maxTrades:'',rules:'',strategies:'',checklist:['Analisar o contexto','Estou emocionalmente bem','Notícias verificadas','Mercado respeitando meu setup','Estou seguindo meu plano'],checked:[]};
function plan(){const p={...planBase,...(S.settings.plan||{})};const pf=(label,k,placeholder='')=>`<div class="field"><label>${label}</label><input data-plan="${k}" value="${esc(p[k])}" placeholder="${esc(placeholder)}"></div>`;return `<div class="plan-grid">${header('Plano de Trade','Seu planejamento operacional — salvo localmente')}
 <div class="card"><h3>◎ Objetivos</h3><div class="grid3">${pf('Meta diária','daily','Ex.: $200')}${pf('Meta semanal','weekly','Ex.: $1.000')}${pf('Meta mensal','monthly','Ex.: $4.000')}</div></div>
 <div class="card"><h3>◷ Gestão de Risco</h3><div class="form-grid">${pf('Risco por operação (%)','risk','Ex.: 1')}${pf('Loss diário','dailyLoss','Ex.: $300 ou 3 trades')}${pf('Loss semanal','weeklyLoss','Ex.: $1.000')}${pf('Máx. de operações por dia','maxTrades','Ex.: 5')}</div></div>
 <div class="card"><h3>☷ Regras Operacionais</h3><div class="field"><textarea data-plan="rules" rows="5">${esc(p.rules)}</textarea></div></div>
 <div class="card"><h3>▤ Estratégias Permitidas</h3><div class="field"><textarea data-plan="strategies" rows="4">${esc(p.strategies)}</textarea></div></div>
 <div class="card"><h3>☑ Checklist Pré-Mercado</h3>${p.checklist.map((x,i)=>`<div class="checklist-item"><input type="checkbox" data-action="checkPlan" data-index="${i}" ${p.checked.includes(i)?'checked':''}><span style="flex:1;${p.checked.includes(i)?'text-decoration:line-through;color:var(--sub)':''}">${esc(x)}</span><button class="iconbtn" title="Excluir item" data-action="removeChecklist" data-index="${i}">♜</button></div>`).join('')}<div class="chiprow"><input id="newChecklist" class="btn" style="flex:1;text-align:left;font-weight:400" placeholder="Adicionar item ao checklist...">${btn('+ Adicionar','addChecklist','small')}</div></div></div>`}
function books(){return header('Livros','Sua biblioteca particular de PDFs',btn('+ Adicionar Livro','addBook','primary'))+(S.books.length?`<div class="book-grid">${S.books.map(b=>`<div class="card book-card"><div class="book-cover">▥</div><strong>${esc(b.title)}</strong><small class="muted">Página ${b.current_page}${b.page_count?' de '+b.page_count:''}</small><div class="actions">${btn('Continuar leitura','readBook','primary small',`data-id="${b.id}"`)}${btn('♜','deleteBook','small',`data-id="${b.id}" title="Excluir livro"`)}</div></div>`).join('')}</div>`:blank('Sua biblioteca está vazia','Adicione PDFs para ler no próprio diário, mantendo um marcador da página atual.','addBook','Adicionar PDF'))}
function bookReader(){const b=S.books.find(x=>x.id===+activeBook);if(!b)return books();return `<div class="page-head"><div><h1>Leitura: ${esc(b.title)}</h1><p class="muted">Ambiente de leitura focada, com acompanhamento da página</p></div>${btn('← Biblioteca','backBooks')}</div><div class="reading-bar"><span>Página salva:</span><input id="bookPage" type="number" min="1" max="${b.page_count||9999}" value="${b.current_page}" style="width:95px" class="btn"><button class="btn" data-action="savePage">Salvar página</button>${btn('Modo tela cheia','fullReader')}<span class="muted">Use o zoom e a navegação do leitor de PDF.</span></div><iframe id="readerFrame" class="reading-frame" src="${esc(b.file)}#page=${b.current_page}&toolbar=1&navpanes=0" title="Leitura de ${esc(b.title)}"></iframe><p class="helper">O visual interno do PDF depende do leitor do seu navegador. Salve a página acima para continuar de onde parou.</p>`}
function cloudPanel(){
 const c=S.cloud||{}, pending=num(c.pending), conflicts=num(c.conflicts);
 const state=c.signed_in ? (c.last_error?'Problema de conexão':'Conectado à nuvem') : 'Somente local';
 return `<div class="card setting-panel cloud-panel"><h3>☁ Sincronização Casa ↔ Escritório</h3>
 <p class="muted">O diário continua salvando neste PC e envia as alterações para seu Supabase ao conectar à internet. Use o mesmo login nos dois computadores.</p>
 <div class="cloud-summary"><b class="${c.last_error?'negative':c.signed_in?'positive':''}">${esc(state)}</b>
 <span>${c.signed_in?'Usuário: '+esc(c.email):'Dados continuam disponíveis offline'}</span></div>
 ${c.signed_in ? `<p class="helper">Pendências locais: <strong>${pending}</strong> · Conflitos a resolver: <strong>${conflicts}</strong> · Última sincronização: ${esc(c.last_sync?c.last_sync.replace('T',' '):'ainda não realizada')}</p>
 <div class="actions">${btn('↻ Sincronizar agora','cloudSync','primary')}${btn('Sair da nuvem','cloudLogout')}</div>
 ${c.last_error?`<p class="cloud-error">${esc(c.last_error)}</p>`:''}
 ${conflicts?`<div class="cloud-conflicts"><h3>Revisar conflitos antes de continuar</h3><p class="muted">O mesmo registro mudou nos dois computadores. Escolha conscientemente qual versão deseja manter.</p><div id="cloudConflictItems">${btn('Carregar conflitos','cloudConflicts')}</div></div>`:''}`:
 `<div class="form-grid" style="margin-top:15px">
 <div class="field field-full"><label>URL do projeto Supabase</label><input id="cloudUrl" autocomplete="off" placeholder="https://seu-projeto.supabase.co" value="${esc(c.url||'')}"></div>
 <div class="field field-full"><label>Chave publishable pública (NUNCA a chave secret/service_role)</label><input id="cloudKey" autocomplete="off" spellcheck="false" placeholder="sb_publishable_..."></div>
 <div class="field"><label>E-mail</label><input id="cloudEmail" type="email" autocomplete="username" placeholder="seu@email.com" value="${esc(c.email||'')}"></div>
 <div class="field"><label>Senha da conta</label><input id="cloudPassword" type="password" autocomplete="current-password" placeholder="Sua senha"></div>
 </div><div class="actions" style="margin-top:15px">${btn('Conectar e sincronizar','cloudLogin','primary')}${btn('Criar conta com este e-mail','cloudSignup')}</div>
 <p class="helper">Primeiro crie um projeto Supabase e execute o arquivo SETUP_SUPABASE.sql no SQL Editor. A senha não é salva; no Windows a sessão é protegida com DPAPI.</p>
 ${c.last_error?`<p class="cloud-error">${esc(c.last_error)}</p>`:''}`}
 <p class="helper">As cópias de segurança ZIP continuam importantes. Não sincronize diretamente o arquivo diario.db por Google Drive ou OneDrive.</p>
 </div>`;
}
function settings(){const names={equity:'Curva de Equity',distribution:'Distribuição Win/Loss',assets:'Performance por Ativo',strategies:'Profit por Estratégia',weekdays:'Profit por Dia',hours:'Tempo / Horários',metrics:'Métricas Profissionais',performance:'Análise de Performance'};const palettes=[['Índigo','#635cf6'],['Azul','#3274ed'],['Verde','#009b78'],['Roxo','#8c58f6'],['Rosa','#f43b90'],['Laranja','#f97316'],['Ciano','#04a5c7'],['Cinza','#373c45']];
 return `<div class="form-narrow">${header('Configurações','Personalize seu dashboard e aparência')}${cloudPanel()}<div class="card setting-panel"><h3>▦ Editor de Layout</h3><p class="split-label">PRESETS</p><div class="preset-list">${['Padrão','Compacto','Analítico','Minimalista'].map(n=>`<button class="btn small ${P.preset===n?'active':''}" data-action="preset" data-val="${n}">${n}</button>`).join('')}</div><p class="split-label" style="margin-top:19px">COLUNAS DO DASHBOARD</p><div class="preset-list">${[2,3,4,5,6].map(n=>`<button class="btn small ${+P.columns===n?'active':''}" data-action="columns" data-val="${n}">${n}</button>`).join('')}</div><p class="split-label" style="margin-top:22px">CARDS EXIBIDOS NO DASHBOARD</p><p class="helper">Arraste os cartões para mudar sua ordem no Dashboard.</p><div class="setting-tiles">${[...new Set([...(P.blocks||[]),...Object.keys(names)])].map(k=>`<label class="setting-tile" draggable="true" data-reorder="${k}" title="Arraste para reorganizar"><input type="checkbox" data-block="${k}" ${(P.blocks||[]).includes(k)?'checked':''}>${names[k]}</label>`).join('')}</div></div><div class="card setting-panel"><h3>◉ Aparência</h3><p class="split-label">TEMA</p><div class="preset-list">${['light','dark'].map(t=>`<button class="btn small ${P.theme===t?'active':''}" data-action="theme" data-val="${t}">${t==='light'?'☼ Claro':'☾ Escuro'}</button>`).join('')}</div><p class="split-label" style="margin-top:21px">COR PRINCIPAL</p><div class="chiprow">${palettes.map(([l,c])=>`<button class="color-dot ${P.primary===c?'active':''}" title="${l}" data-action="primary" data-val="${c}" style="background:${c}"></button>`).join('')}<input id="customColor" type="color" value="${P.primary}" title="Cor personalizada"></div><p class="split-label" style="margin-top:24px">MODO COMPACTO</p><label class="switch-row"><input id="compactToggle" type="checkbox" ${P.compact?'checked':''}> Reduzir espaçamentos</label><div class="separator"></div>${btn('Restaurar padrões','resetPrefs')}</div>
 <div class="card setting-panel"><h3>◷ Contas e Estratégias</h3><p class="muted">Salve contas com capital inicial e estratégias para reutilizar no cadastro das operações.</p><div class="actions" style="margin-top:15px">${btn('+ Nova Conta','addAccount','primary small')}${btn('+ Nova Estratégia','addStrategy','small')}</div><div class="grid2" style="margin-top:15px"><div>${S.accounts.map(a=>`<div class="data-row"><span>${esc(a.name)} <small>(${amount(a.initial_capital,a.currency)})</small></span><button class="iconbtn" title="Excluir conta" data-action="deleteAccount" data-id="${a.id}">♜</button></div>`).join('')}</div><div>${S.strategies.map(a=>`<div class="data-row"><span>${esc(a.name)}</span><button class="iconbtn" title="Excluir estratégia" data-action="deleteStrategy" data-id="${a.id}">♜</button></div>`).join('')}</div></div></div>
 <div class="card setting-panel"><h3>♧ Segurança e Backup</h3><p class="muted">Exporte um ZIP com os dados, prints e livros. Recomendamos guardar cópias fora desta pasta.</p><div class="actions" style="margin-top:17px">${btn('↓ Fazer backup completo','backup','primary')}${btn('↑ Restaurar backup','restoreBackup')}</div><p class="helper">Ao restaurar, os registros atuais serão substituídos pelo backup. Uma cópia do banco anterior será mantida em data/backup_antes_restaurar.db.</p></div></div>`}
function profile(){const p=S.settings.profile||{},m=metrics(),days=[...m.days],bestDay=days.length?Math.max(...days.map(x=>x[1])):0,worstDay=days.length?Math.min(...days.map(x=>x[1])):0,totalSecs=S.sessions.reduce((s,x)=>s+num(x.seconds),0),months=new Set([...m.days.keys()].map(x=>x.slice(0,7))).size,weeks=new Set([...m.days.keys()].map(x=>{let d=new Date(x+'T12:00:00');d.setDate(d.getDate()-(d.getDay()+6)%7);return localDate(d)})).size;return `<div class="form-narrow">${header('Perfil','Seu espaço de evolução como trader',btn('✎ Editar perfil','editProfile'))}<div class="card profile-top"><div class="avatar-large" ${p.avatar?`style="background-image:url('${esc(p.avatar)}')"`:''}>${p.avatar?'':esc((p.name||'DT').split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</div><div style="flex:1"><strong>${esc(p.name||'Meu Perfil')}</strong><p class="muted">${esc(p.email||'Perfil local • sem login obrigatório')}</p><small class="muted">${esc(p.bio||'Evoluindo!')}</small></div></div><div class="smallspace"></div><div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Lucro acumulado',amount(m.net),'↗','positive')}${stat('Win Rate',pct(m.winrate),'◎','primary-text')}${stat('Profit Factor',m.pf===Infinity?'∞':fnum(m.pf),'▤')}${stat('RR médio',fnum(m.avgRR),'◷')}${stat('Total de Trades',m.count,'▥')}${stat('Tempo de Tela',timefmt(totalSecs),'◷')}</div><div class="card chart-card">${cardTitle('Curva de Capital')}${chartLine(m.equity,220)}</div><div class="card subcard" style="margin-bottom:15px"><h3>Resumo de Performance</h3><div class="grid3">${[['Melhor dia',amount(bestDay)],['Pior dia',amount(worstDay)],['Média diária',amount(days.length?m.net/days.length:0)],['Média semanal',amount(m.net/Math.max(1,weeks))],['Média mensal',amount(m.net/Math.max(1,months))],['Capital inicial total',amount(S.accounts.reduce((a,c)=>a+num(c.initial_capital),0))]].map(([l,v])=>`<div><p class="muted">${l}</p><strong>${v}</strong></div>`).join('')}</div></div>${btn('Abrir calendário','goCalendar')}</div>`}
function openModal(title,body,footer=''){$('#modalRoot').innerHTML=`<div class="modal-bg" id="modalBackdrop"><div class="modal-box" role="dialog" aria-modal="true"><div class="modal-top"><h2>${esc(title)}</h2><button class="iconbtn" data-action="closeModal">✕</button></div>${body}${footer?`<div class="form-actions">${footer}</div>`:''}</div></div>`}
function closeModal(){$('#modalRoot').innerHTML=''}
function modalAccount(){openModal('Cadastrar nova conta',`<div class="form-grid"><div class="field"><label>Nome da conta *</label><input id="newAccountName" placeholder="Ex.: FTMO 10K"></div><div class="field"><label>Tipo de conta</label><select id="newAccountKind"><option>Pessoal</option><option>Mesa proprietária</option><option>Demo</option><option>Corretora</option></select></div><div class="field"><label>Capital inicial *</label><input id="newAccountCapital" type="number" min="0" step="any" placeholder="Ex.: 10000"></div><div class="field"><label>Moeda</label><select id="newAccountCurrency"><option value="USD">USD ($)</option><option value="BRL">BRL (R$)</option><option value="EUR">EUR (€)</option></select></div></div><p class="info-note" style="margin-top:16px">O capital inicial é necessário para calcular a evolução e o saldo dessa conta. Contas de moedas diferentes serão tratadas separadamente; o Dashboard consolida os valores numéricos sem conversão cambial.</p>`,btn('Cancelar','closeModal')+btn('Salvar Conta','saveAccount','primary'))}
function modalStrategy(){openModal('Cadastrar nova estratégia',`<div class="field"><label>Nome da estratégia *</label><input id="newStrategyName" placeholder="Ex.: Variação do Ajuste"></div>`,btn('Cancelar','closeModal')+btn('Salvar Estratégia','saveStrategy','primary'))}
function modalProfile(){const p=S.settings.profile||{};openModal('Editar perfil',`<div class="form-grid"><div class="field"><label>Nome</label><input id="proName" value="${esc(p.name||'')}"></div><div class="field"><label>E-mail (opcional)</label><input id="proEmail" type="email" value="${esc(p.email||'')}"></div><div class="field field-full"><label>Bio</label><textarea id="proBio">${esc(p.bio||'')}</textarea></div><div class="field field-full"><label>Foto de perfil</label><input type="file" id="profileImage" accept="image/*"><small class="muted">Opcional. O arquivo será guardado localmente.</small></div></div>`,btn('Cancelar','closeModal')+btn('Salvar Perfil','saveProfile','primary'))}
function modalReport(){const today=localDate(),m=today.slice(0,7);openModal('Gerar Relatório de Performance',`<p class="muted" style="margin-bottom:20px">Escolha um período. O relatório abre em uma aba pronta para impressão ou para salvar como PDF.</p><div class="form-grid"><div class="field"><label>Data inicial</label><input id="repStart" type="date" value="${lastReportDates.start||m+'-01'}"></div><div class="field"><label>Data final</label><input id="repEnd" type="date" value="${lastReportDates.end||today}"></div></div><p class="helper">Na janela de impressão do navegador, selecione “Salvar como PDF” para gerar o arquivo.</p>`,btn('Cancelar','closeModal')+btn('Imprimir / Salvar em PDF','printReport','primary'))}
function reportPrint(){const start=$('#repStart').value,end=$('#repEnd').value;if(!start||!end||start>end)throw Error('Selecione um período válido');lastReportDates={start,end};const trades=activeTrades().filter(t=>t.date>=start&&t.date<=end),m=metrics(trades);
 const group=grouped(trades,x=>x.asset),strat=grouped(trades,x=>x.strategy||'Sem estratégia');const rows=trades.map(t=>`<tr><td>${datePt(t.date)}</td><td>${esc(t.asset)}</td><td>${esc(t.direction)}</td><td>${esc(t.strategy||'—')}</td><td>${esc(accountName(t))}</td><td class="${tnet(t)>=0?'pos':'neg'}">${money(tnet(t))}</td></tr>`).join('');const figures=[['Resultado líquido',money(m.net)],['Trades',m.count],['Win Rate',pct(m.winrate)],['Profit Factor',m.pf===Infinity?'∞':fnum(m.pf)],['Expectativa',amount(m.expectancy)],['Drawdown máximo',amount(m.drawdown)],['Melhor operação',amount(m.best)],['Pior operação',amount(m.worst)],['Média Gain',amount(m.avgGain)],['Média Loss',amount(m.avgLoss)],['Consistência',pct(m.consistency)],['RR médio',fnum(m.avgRR)]];
 const logo=(S.settings.profile||{}).name||'D_Trading';const popup=window.open('','_blank');if(!popup)throw Error('Seu navegador bloqueou a janela do relatório');const printable=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório D_Trading ${start} - ${end}</title><style>body{font:12px 'Segoe UI',Arial,sans-serif;color:#202637;margin:35px}h1{font-size:25px;margin:0}h2{font-size:16px;margin-top:25px;border-bottom:1px solid #ddd;padding-bottom:9px}.note{color:#697589}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.card{border:1px solid #e0e4e9;border-radius:9px;padding:14px}.card small{display:block;color:#768195;font-size:10px;text-transform:uppercase;margin-bottom:8px}.card strong{font-size:18px}.pos{color:#0a9b70}.neg{color:#e14351}table{width:100%;border-collapse:collapse;font-size:11px}th,td{padding:9px 7px;border-bottom:1px solid #e8ecf2;text-align:left}th{background:#f4f6fa}.footer{margin-top:24px;font-size:10px;color:#8c96a5}@media print{@page{margin:15mm}.no-print{display:none}body{margin:0}tr,.card{break-inside:avoid}}</style></head><body><button class="no-print" onclick="window.print()" style="padding:11px 18px;background:#615cf6;color:white;border:0;border-radius:8px;cursor:pointer;float:right">Imprimir / Salvar PDF</button><h1>D_Trading • Relatório</h1><p class="note">${esc(logo)} · ${datePt(start)} a ${datePt(end)} · Gerado em ${datePt(localDate())}</p><h2>Resumo executivo</h2><div class="cards">${figures.map(([k,v])=>`<div class="card"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><h2>Performance por ativo</h2><table><thead><tr><th>Ativo</th><th>Resultado líquido</th></tr></thead><tbody>${group.map(x=>`<tr><td>${esc(x.key)}</td><td>${money(x.value)}</td></tr>`).join('')}</tbody></table><h2>Performance por estratégia</h2><table><thead><tr><th>Estratégia</th><th>Resultado líquido</th></tr></thead><tbody>${strat.map(x=>`<tr><td>${esc(x.key)}</td><td>${money(x.value)}</td></tr>`).join('')}</tbody></table><h2>Operações registradas (${trades.length})</h2><table><thead><tr><th>Data</th><th>Ativo</th><th>Direção</th><th>Estratégia</th><th>Conta</th><th>Resultado líquido</th></tr></thead><tbody>${rows||'<tr><td colspan="6">Sem operações no período</td></tr>'}</tbody></table><p class="footer">Dados extraídos do diário local. Valores agregados sem conversão entre moedas diferentes. Relatório de uso pessoal.</p></body></html>`;
 popup.document.open();popup.document.write(printable);popup.document.close();closeModal();toast('Relatório pronto para imprimir ou salvar em PDF.')}
function saveBookDialog(){openModal('Adicionar livro em PDF',`<div class="form-grid"><div class="field field-full"><label>Título do livro</label><input id="bookTitle" placeholder="Ex.: Análise Técnica Baseada em Evidências"></div><div class="field field-full"><label>PDF</label><input id="bookFile" type="file" accept="application/pdf,.pdf"></div></div><p class="helper">O livro será armazenado no computador. PDF até 50 MB.</p>`,btn('Cancelar','closeModal')+btn('Salvar Livro','saveBook','primary'))}
async function saveBook(){const f=$('#bookFile')?.files?.[0];if(!f)throw Error('Selecione um PDF');const title=$('#bookTitle').value.trim()||f.name.replace(/\.pdf$/i,'');await api('/api/books',{title,data:await readData(f)});closeModal();await reload();render();toast('Livro adicionado à biblioteca')}
async function saveAccount(){const name=$('#newAccountName').value.trim(),kind=$('#newAccountKind').value,initial_capital=$('#newAccountCapital').value,currency=$('#newAccountCurrency').value;if(!name)throw Error('Informe o nome da conta');if(initial_capital==='')throw Error('Informe o capital inicial (pode ser zero)');const a=await api('/api/accounts',{name,kind,initial_capital,currency});if(page==='operation')draft.accountId=a.id;closeModal();await reload();render();toast('Conta cadastrada com capital inicial')}
async function saveStrategy(){const name=$('#newStrategyName').value.trim();if(!name)throw Error('Informe o nome da estratégia');await api('/api/strategies',{name});if(page==='operation')draft.strategy=name;closeModal();await reload();render();toast('Estratégia cadastrada')}
async function saveProfile(){const p={...S.settings.profile,name:$('#proName').value.trim(),email:$('#proEmail').value.trim(),bio:$('#proBio').value.trim()};const img=$('#profileImage').files[0];if(img){const f=await api('/api/upload',{data:await readData(img)});p.avatar=f.path}await saveSettings('profile',p);closeModal();render();toast('Perfil atualizado')}

function tickTimer(){const t=S.timer||{};const display=num(t.elapsed)+(t.running&&t.started_at?Math.max(0,Date.now()/1000-num(t.started_at)):0);$('#timerClock').textContent=timefmt(display);$('#timerPlay').textContent=t.running?'Ⅱ':'▶';$('#timerPlay').title=t.running?'Pausar estudo':'Iniciar estudo'}
function updateTimer(){tickTimer()}
async function timerAction(action){S.timer=await api('/api/timer',{action});await reload();if(page==='dashboard'||page==='profile')render();tickTimer()}
async function doDeleteTrade(id){if(!confirm('Excluir esta operação e seus prints vinculados? Esta ação não pode ser desfeita.'))return;await api('/api/trades/delete',{id});await reload();nav('feed');toast('Operação excluída')}
async function doDeleteBook(id){if(!confirm('Excluir este livro da sua biblioteca?'))return;await api('/api/books/delete',{id});await reload();render();toast('Livro excluído')}

function openStudy(tradeId,index){const t=S.trades.find(x=>x.id===+tradeId),src=t?.images?.[index];if(!src)return toast('O print não foi encontrado');study={tradeId:+tradeId,index:+index,tool:'pen',color:'#f54747',width:4,undo:[]};$('#modalRoot').innerHTML=`<div class="study-bg" id="studyApp"><div class="study-toolbar"><button data-action="closeStudy">✕ Sair</button><b style="margin-right:12px">MODO DE ESTUDO · ${esc(t.asset)}</b><button data-action="studyTool" data-tool="pen" class="selected">✎ Caneta</button><button data-action="studyTool" data-tool="line">／ Linha</button><button data-action="studyTool" data-tool="rect">▢ Caixa</button><button data-action="studyTool" data-tool="arrow">→ Seta</button><button data-action="studyTool" data-tool="text">T Texto</button><button data-action="studyTool" data-tool="erase">◌ Borracha</button><input type="color" id="studyColor" value="#f54747" title="Cor"><select id="studyWidth"><option value="2">Fino</option><option value="4" selected>Médio</option><option value="8">Grosso</option></select><button data-action="undoStudy">↶ Desfazer</button><button data-action="clearStudy">♜ Limpar</button><button data-action="saveStudy" style="background:var(--primary)">▣ Salvar no trade</button></div><div class="study-stage"><div class="study-canvas-wrap"><img id="studyOriginal" src="${esc(src)}" alt="Print para estudo"><canvas id="studyCanvas"></canvas></div></div></div>`;
 const img=$('#studyOriginal');img.onload=()=>initStudyCanvas(img);if(img.complete&&img.naturalWidth)initStudyCanvas(img)}
function initStudyCanvas(img){const cv=$('#studyCanvas');if(!cv)return;cv.width=img.naturalWidth;cv.height=img.naturalHeight;const ctx=cv.getContext('2d');let drawing=false,start=null,snapshot=null;
 const point=(ev)=>{const r=cv.getBoundingClientRect();return {x:(ev.clientX-r.left)*cv.width/r.width,y:(ev.clientY-r.top)*cv.height/r.height}};
 const prepare=()=>{ctx.lineWidth=study.width*cv.width/1000;ctx.strokeStyle=study.color;ctx.fillStyle=study.color;ctx.lineJoin='round';ctx.lineCap='round';ctx.globalCompositeOperation=study.tool==='erase'?'destination-out':'source-over'};
 function arrow(a,b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();const angle=Math.atan2(b.y-a.y,b.x-a.x),len=18*cv.width/1000;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-len*Math.cos(angle-.55),b.y-len*Math.sin(angle-.55));ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-len*Math.cos(angle+.55),b.y-len*Math.sin(angle+.55));ctx.stroke()}
 function shape(a,b){prepare();if(study.tool==='line'){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}else if(study.tool==='rect'){ctx.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y)}else if(study.tool==='arrow')arrow(a,b)}
 cv.onpointerdown=(ev)=>{ev.preventDefault();const p=point(ev);study.undo.push(ctx.getImageData(0,0,cv.width,cv.height));if(study.undo.length>10)study.undo.shift();if(study.tool==='text'){prepare();const text=prompt('Digite o texto da anotação:');if(text){ctx.font=`bold ${Math.max(22,cv.width*.026)}px Arial`;ctx.fillText(text.slice(0,150),p.x,p.y)}else study.undo.pop();return}drawing=true;start=p;snapshot=ctx.getImageData(0,0,cv.width,cv.height);prepare();if(study.tool==='pen'||study.tool==='erase'){ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke()}cv.setPointerCapture(ev.pointerId)};
 cv.onpointermove=(ev)=>{if(!drawing)return;let p=point(ev);if(['pen','erase'].includes(study.tool)){prepare();ctx.lineTo(p.x,p.y);ctx.stroke()}else{ctx.putImageData(snapshot,0,0);shape(start,p)}};
 cv.onpointerup=(ev)=>{if(!drawing)return;drawing=false;if(!['pen','erase'].includes(study.tool)){ctx.putImageData(snapshot,0,0);shape(start,point(ev))}ctx.globalCompositeOperation='source-over'};
}
async function saveStudy(){const t=S.trades.find(x=>x.id===study.tradeId);if(!t)return;const img=$('#studyOriginal'),canvas=$('#studyCanvas');const merged=document.createElement('canvas');merged.width=canvas.width;merged.height=canvas.height;const ctx=merged.getContext('2d');ctx.drawImage(img,0,0,merged.width,merged.height);ctx.drawImage(canvas,0,0);const data=merged.toDataURL('image/png');const out=await api('/api/upload',{data});const copy=structuredClone(t);delete copy.id;copy.images[study.index]=out.path;await api('/api/trades',{id:t.id,trade:copy});closeModal();await reload();render();toast('Anotações salvas no print da operação')}

function render(){const el=$('#content');if(!el)return;switch(page){case 'dashboard':el.innerHTML=dashboard();break;case 'feed':el.innerHTML=feed();break;case 'operation':el.innerHTML=operation();computed();break;case 'calendar':el.innerHTML=calendar();break;case 'details':el.innerHTML=details(window.currentTradeId);break;case 'plan':el.innerHTML=plan();break;case 'books':el.innerHTML=activeBook?bookReader():books();break;case 'settings':el.innerHTML=settings();break;case 'profile':el.innerHTML=profile();break;default:el.innerHTML=dashboard()}}
async function cloudLogin(){
 const data={url:$('#cloudUrl').value.trim(),key:$('#cloudKey').value.trim(),email:$('#cloudEmail').value.trim(),password:$('#cloudPassword').value};
 if(!data.email||!data.password||!data.url||!data.key)throw Error('Preencha a URL, a chave publishable, o e-mail e a senha');
 await api('/api/cloud/login',data);await reload();render();toast('Conectado! A sincronização inicial começou.');
}
async function cloudSignup(){
 const data={url:$('#cloudUrl').value.trim(),key:$('#cloudKey').value.trim(),email:$('#cloudEmail').value.trim(),password:$('#cloudPassword').value};
 if(!data.email||!data.password||!data.url||!data.key)throw Error('Preencha os quatro campos');
 await api('/api/cloud/signup',data);toast('Cadastro enviado. Confira o e-mail de confirmação e depois clique em Conectar.');
}
async function cloudConflicts(){
 const r=await api('/api/cloud/conflicts');const box=$('#cloudConflictItems');if(!box)return;
 const kindNames={account:'Conta',strategy:'Estratégia',trade:'Operação',book:'Livro',session:'Tempo de tela',settings:'Configuração'};
 box.innerHTML=(r.items||[]).map((x,i)=>{
 const n=x.local?.name||x.local?.title||x.local?.key||x.local?.payload?.asset||x.remote?.data?.name||x.remote?.data?.title||x.remote?.data?.payload?.asset||'';
 const id=esc(x.sync_id),type=esc(x.kind);
 return `<div class="cloud-conflict"><b>${esc(kindNames[x.kind]||x.kind)} ${esc(n)}</b><p class="muted">O registro foi alterado neste computador e na nuvem. Você pode manter o local ou usar o da nuvem.</p><div class="actions">
 <button class="btn small" data-action="cloudResolve" data-kind="${type}" data-sid="${id}" data-val="cloud">Usar versão da nuvem</button>
 <button class="btn small primary" data-action="cloudResolve" data-kind="${type}" data-sid="${id}" data-val="local">Manter minha versão local</button></div></div>`;
 }).join('')||'<p>Sem conflitos pendentes.</p>';
}
async function cloudRefresh(){
 try{
   const status=await api('/api/cloud/status');
   if(!S.cloud || status.data_version!==S.cloud.data_version){
     if(page!=='operation' && !(page==='books' && activeBook)){await reload();render()}
     else S.cloud={...status,data_version:S.cloud?.data_version??-1};
   } else {S.cloud=status;}
   const dot=$('#syncBadge');if(dot){dot.textContent=status.signed_in?(status.last_error?'☁ Atenção':status.conflicts?'☁ Conflitos':status.pending?'☁ Pendente':'☁ Sincronizado'):'◯ Local';
     dot.title=status.last_error||`${status.pending} pendências; ${status.conflicts} conflitos`;}
 }catch(e){console.warn('Status de sincronização indisponível',e)}
}
async function command(node){const act=node.dataset.action,id=+node.dataset.id,idx=+node.dataset.index,val=node.dataset.val;
 switch(act){
 case 'cloudLogin':await cloudLogin();break;
 case 'cloudSignup':await cloudSignup();break;
 case 'cloudSync':await api('/api/cloud/sync',{});toast('Sincronização solicitada.');setTimeout(cloudRefresh,1600);break;
 case 'cloudLogout':if(confirm('Sair da nuvem neste computador? Os dados locais serão preservados.')){await api('/api/cloud/logout',{});await reload();render()}break;
 case 'cloudConflicts':await cloudConflicts();break;
 case 'cloudResolve':if(confirm(val==='local'?'Substituir a versão da nuvem pela versão deste computador?':'Substituir a versão local pela versão da nuvem?')){await api('/api/cloud/resolve',{kind:node.dataset.kind,id:node.dataset.sid,choice:val});await reload();render();toast('Conflito resolvido')}break;
 case 'newTrade':newTrade();break;
 case 'goFeed':nav('feed');break;
 case 'goCalendar':nav('calendar');break;
 case 'closeModal':closeModal();break;
 case 'addAccount':modalAccount();break;
 case 'addStrategy':modalStrategy();break;
 case 'saveAccount':await saveAccount();break;
 case 'saveStrategy':await saveStrategy();break;
 case 'tab':formTab=node.dataset.tab;render();break;
 case 'rate':draft.rating=+val;render();break;
 case 'saveTrade':await saveTrade();break;
 case 'details':window.currentTradeId=id;nav('details');break;
 case 'editTrade':editTrade(id);break;
 case 'deleteTrade':await doDeleteTrade(id);break;
 case 'prevMonth':calendarAt.setMonth(calendarAt.getMonth()-1);selectedDay='';render();break;
 case 'nextMonth':calendarAt.setMonth(calendarAt.getMonth()+1);selectedDay='';render();break;
 case 'calendarDay':selectedDay=node.dataset.date;render();break;
 case 'closeDay':selectedDay='';render();break;
 case 'uploadImage':$('#hiddenImage').click();break;
 case 'removeDraftImage':if(confirm('Excluir este print da operação?')){draft.images.splice(idx,1);render()}break;
 case 'previewDraft':if(editingId){openStudy(editingId,idx)}else{openModal('Visualizar print',`<img src="${esc(draft.images[idx])}" style="max-width:100%">`,btn('Fechar','closeModal'))}break;
 case 'study':openStudy(id,idx);break;
 case 'closeStudy':closeModal();break;
 case 'studyTool':study.tool=node.dataset.tool;$$('[data-action="studyTool"]').forEach(b=>b.classList.toggle('selected',b===node));break;
 case 'undoStudy':{const cv=$('#studyCanvas');if(cv&&study.undo.length){cv.getContext('2d').putImageData(study.undo.pop(),0,0)}}break;
 case 'clearStudy':{const cv=$('#studyCanvas');if(cv&&confirm('Limpar as marcações não salvas?')){study.undo.push(cv.getContext('2d').getImageData(0,0,cv.width,cv.height));cv.getContext('2d').clearRect(0,0,cv.width,cv.height)}}break;
 case 'saveStudy':await saveStudy();break;
 case 'report':modalReport();break;
 case 'printReport':reportPrint();break;
 case 'addBook':saveBookDialog();break;
 case 'saveBook':await saveBook();break;
 case 'readBook':activeBook=id;render();break;
 case 'backBooks':activeBook=null;render();break;
 case 'deleteBook':await doDeleteBook(id);break;
 case 'savePage':{const v=+$('#bookPage').value||1;await api('/api/books/page',{id:activeBook,page:v});await reload();render();toast('Página de leitura salva')}break;
 case 'fullReader':{const v=$('#readerFrame');if(!document.fullscreenElement && v?.requestFullscreen)await v.requestFullscreen();else if(document.exitFullscreen)await document.exitFullscreen()}break;
 case 'editProfile':modalProfile();break;
 case 'saveProfile':await saveProfile();break;
 case 'preset':P.preset=val;await saveSettings('preferences',P);render();break;
 case 'columns':P.columns=+val;await saveSettings('preferences',P);render();break;
 case 'theme':P.theme=val;await saveSettings('preferences',P);render();break;
 case 'primary':P.primary=val;await saveSettings('preferences',P);render();break;
 case 'resetPrefs':if(confirm('Restaurar as configurações visuais padrão?')){await saveSettings('preferences',basePrefs);render()}break;
 case 'backup':window.location.href='/api/backup';toast('O download do backup foi solicitado');break;
 case 'restoreBackup':if(confirm('Restaurar backup substituirá os registros atuais. Faça um backup antes de continuar. Deseja escolher um arquivo?'))$('#hiddenBackup').click();break;
 case 'deleteAccount':if(confirm('Excluir esta conta cadastrada?')){await api('/api/accounts/delete',{id});await reload();render()}break;
 case 'deleteStrategy':if(confirm('Excluir esta estratégia da lista? As operações antigas manterão o nome usado.')){await api('/api/strategies/delete',{id});await reload();render()}break;
 case 'checkPlan':{const p={...planBase,...(S.settings.plan||{})};let arr=new Set(p.checked||[]);if(node.checked)arr.add(idx);else arr.delete(idx);p.checked=[...arr];await saveSettings('plan',p);render()}break;
 case 'removeChecklist':if(confirm('Excluir item do checklist?')){const p={...planBase,...(S.settings.plan||{})};p.checklist.splice(idx,1);p.checked=[];await saveSettings('plan',p);render()}break;
 case 'addChecklist':{const name=$('#newChecklist').value.trim();if(!name)throw Error('Digite um item');const p={...planBase,...(S.settings.plan||{})};p.checklist.push(name);await saveSettings('plan',p);render()}break;
 }
}
document.addEventListener('click',e=>{const navBtn=e.target.closest('[data-page]');if(navBtn){if(navBtn.dataset.page==='operation')newTrade();else nav(navBtn.dataset.page);return}const action=e.target.closest('[data-action]');if(action){e.preventDefault();e.stopPropagation();run(()=>command(action))}});
document.addEventListener('input',e=>{const n=e.target;if(n.dataset.field){draft[n.dataset.field]=n.type==='checkbox'?n.checked:n.value;if(['entry','exit','stop','direction','risk','pnl','fees','accountId'].includes(n.dataset.field))computed()}if(n.id==='studyColor')study.color=n.value;if(n.id==='studyWidth')study.width=+n.value});
document.addEventListener('change',e=>{const n=e.target;if(n.dataset.field){draft[n.dataset.field]=n.type==='checkbox'?n.checked:n.value;if(n.dataset.field==='noTrade'){render();return}if(n.dataset.field==='accountId'||n.dataset.field==='start'||n.dataset.field==='end'){render();return}}
 if(n.dataset.plan){const p={...planBase,...(S.settings.plan||{})};p[n.dataset.plan]=n.value;run(async()=>{await saveSettings('plan',p);toast('Plano atualizado')})}
 if(n.dataset.block){let set=new Set(P.blocks||[]);if(n.checked)set.add(n.dataset.block);else set.delete(n.dataset.block);P.blocks=[...new Set([...(P.blocks||[]),...['equity','distribution','assets','strategies','weekdays','hours','metrics','performance']])].filter(k=>set.has(k));run(()=>saveSettings('preferences',P))}
 if(n.id==='compactToggle'){P.compact=n.checked;run(async()=>{await saveSettings('preferences',P);render()})}
 if(n.id==='customColor'){P.primary=n.value;run(async()=>{await saveSettings('preferences',P);render()})}
});
$('#hiddenImage').addEventListener('change',e=>run(async()=>{if(e.target.files.length)await uploadImages([...e.target.files]);e.target.value=''}));
$('#hiddenBackup').addEventListener('change',e=>run(async()=>{const f=e.target.files[0];if(!f)return;const data=await readData(f);await api('/api/backup/restore',{data});toast('Backup restaurado. Atualizando...');await reload();nav('dashboard');e.target.value=''}));
let draggingKey='';
document.addEventListener('dragstart',e=>{const t=e.target.closest?.('[data-reorder]');if(t){draggingKey=t.dataset.reorder;e.dataTransfer?.setData('text/plain',draggingKey)}});
document.addEventListener('dragover',e=>{if(e.target.closest?.('[data-reorder]'))e.preventDefault()});
document.addEventListener('drop',e=>{const t=e.target.closest?.('[data-reorder]');if(!t||!draggingKey)return;e.preventDefault();const target=t.dataset.reorder;if(target===draggingKey)return;let order=$$('[data-reorder]').map(x=>x.dataset.reorder);order=order.filter(k=>k!==draggingKey);order.splice(order.indexOf(target),0,draggingKey);P.blocks=order.filter(k=>(P.blocks||[]).includes(k));draggingKey='';run(async()=>{await saveSettings('preferences',P);render()})});
document.addEventListener('paste',e=>{if(page!=='operation'||$('#studyApp'))return;const files=[...e.clipboardData.items].filter(it=>it.kind==='file'&&it.type.startsWith('image/')).map(it=>it.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();run(()=>uploadImages(files))}});
$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#timerPlay').addEventListener('click',()=>run(()=>timerAction(S.timer.running?'pause':'start')));
$('#timerReset').addEventListener('click',()=>run(async()=>{if(confirm('Zerar o cronômetro atual? O tempo já registrado continuará nas métricas.'))await timerAction('reset')}));
$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){toast('Tela cheia não está disponível neste navegador')}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modalRoot').innerHTML)closeModal()});
async function boot(){try{await reload();newTrade();nav('dashboard');setInterval(tickTimer,1000);setInterval(cloudRefresh,10000);cloudRefresh()}catch(e){$('#content').innerHTML=`<div class="card pad">${blank('Não foi possível iniciar o diário','Feche e reabra o arquivo INICIAR_DIARIO.bat. Detalhe: '+e.message)}</div>`}}
boot();